SELECT r.id, r.user_id, r.provider, r.created_at, r.updated_at, r.expires_at FROM (SELECT data_rows.id, data_rows.should_delete, data_rows.user_id, data_rows.provider, data_rows.created_at, data_rows.updated_at, data_rows.expires_at FROM  (SELECT 0 AS should_delete, `id`, `user_id`, `provider`, `created_at`, `updated_at`, `expires_at` FROM session)  data_rows) r WHERE $criteria.CompositeIn("r", $WriterKeys)